// k6-load-test.js
import http from 'k6/http';
import { check, sleep, group } from 'k6';
import { Rate, Trend } from 'k6/metrics';

// 自定义指标
const errorRate = new Rate('errors');
const orderDuration = new Trend('order_duration', true);

export const options = {
  scenarios: {
    // 场景1：恒定负载
    constant_load: {
      executor: 'constant-arrival-rate',
      rate: 100,
      timeUnit: '1s',
      duration: '5m',
      preAllocatedVUs: 50,
      maxVUs: 200,
    },
    // 场景2：阶梯加压
    ramp_up: {
      executor: 'ramping-arrival-rate',
      startRate: 10,
      timeUnit: '1s',
      preAllocatedVUs: 20,
      maxVUs: 500,
      stages: [
        { target: 50, duration: '2m' },
        { target: 100, duration: '3m' },
        { target: 200, duration: '2m' },
        { target: 500, duration: '3m' },
      ],
    },
    // 场景3：峰值测试
    spike: {
      executor: 'shared-iterations',
      vus: 1000,
      iterations: 5000,
      maxDuration: '2m',
      startTime: '12m',  // 在前两个场景后执行
    },
  },
  thresholds: {
    http_req_duration: ['p(50)<100', 'p(95)<300', 'p(99)<800'],
    http_req_failed: ['rate<0.01'],
    errors: ['rate<0.05'],
    order_duration: ['p(95)<500'],
  },
};

const BASE_URL = __ENV.BASE_URL || 'http://api-service:8080';

export default function () {
  group('API Health', () => {
    const res = http.get(`${BASE_URL}/healthz`);
    check(res, { 'health ok': (r) => r.status === 200 });
  });

  group('Create Order', () => {
    const payload = JSON.stringify({
      item: `product-${Math.floor(Math.random() * 100)}`,
      quantity: Math.floor(Math.random() * 5) + 1,
    });
    const params = {
      headers: { 'Content-Type': 'application/json' },
    };
    const start = Date.now();
    const res = http.post(`${BASE_URL}/api/orders`, payload, params);
    orderDuration.add(Date.now() - start);

    const success = check(res, {
      'order created': (r) => r.status === 201,
      'has order id': (r) => r.json('id') !== undefined,
    });
    errorRate.add(!success);
  });

  sleep(Math.random() * 2);
}

# locustfile.py
from locust import HttpUser, task, between
from locust.runners import MasterRunner
import random

class APIUser(HttpUser):
    wait_time = between(0.5, 2.0)

    def on_start(self):
        # 登录获取 token
        resp = self.client.post("/auth/login", json={
            "username": f"user-{random.randint(1,1000)}",
            "password": "test-pass"
        })
        self.token = resp.json().get("token", "")
        self.client.headers["Authorization"] = f"Bearer {self.token}"

    @task(5)
    def get_products(self):
        self.client.get("/api/products?page=1&limit=20")

    @task(3)
    def create_order(self):
        self.client.post("/api/orders", json={
            "items": [{"sku": f"SKU-{random.randint(1,500)}", "qty": 1}]
        })

    @task(1)
    def search(self):
        self.client.get(f"/api/search?q=product-{random.randint(1,100)}")
